// 继承版本: 强耦合
class BaseList extends ArrayList<String> {
  private int addCount = 0;
  @Override public boolean add(String s) {
    addCount++;
    return super.add(s);
  }
  public int getAddCount() { return addCount; }
}

// 组合版本: 只依赖公开行为
class WrappedList {
  private final List<String> inner = new ArrayList<>();
  private int addCount = 0;

  public boolean add(String s) {
    addCount++;
    return inner.add(s);
  }
  public int getAddCount() { return addCount; }
  public int size() { return inner.size(); }
}

interface Shape { double area(); }

class Circle implements Shape {
  private final double r;
  Circle(double r) { this.r = r; }
  public double area() { return Math.PI * r * r; }
}

class Rect implements Shape {
  private final double w, h;
  Rect(double w, double h) { this.w = w; this.h = h; }
  public double area() { return w * h; }
}

public class PolyDemo {
  static double total(Shape[] shapes) {
    double sum = 0;
    for (Shape s : shapes) sum += s.area();
    return sum;
  }

  public static void main(String[] args) {
    Shape[] arr = { new Circle(1), new Rect(2, 3) };
    System.out.println(total(arr));
  }
}

abstract class Shape {
  protected final String name;

  Shape(String name) { this.name = name; }

