// 方案一: 抽象类 (共享状态和行为)
abstract class AbstractRepo {
  protected final Map<String, String> cache = new HashMap<>();
  public String find(String id) {
    return cache.computeIfAbsent(id, this::load);
  }
  protected abstract String load(String id);
}

// 方案二: 接口 (只要能力)
interface Repo {
  String find(String id);
}

// 组合方案: 接口定契约, 抽象类给实现
abstract class BaseRepo implements Repo {
  protected final Map<String, String> cache = new HashMap<>();
  public final String find(String id) {
    return cache.computeIfAbsent(id, this::load);
  }
  protected abstract String load(String id);
}

