public class Outer {
  private int field = 1;
  private static int sField = 2;

  class Inner {                       // 成员内部类
    int read() { return field + sField; }
  }

  static class Nested {               // 静态嵌套类
    int read() { return sField; }
  }

  void method() {
    class Local {                     // 局部内部类
      int read() { return field; }
    }
    System.out.println(new Local().read());

    Runnable r = new Runnable() {     // 匿名内部类
      public void run() { System.out.println(field); }
    };
    r.run();
  }
}

