// 同一个 roam() 调用有三个落点：Canine / Feline / Animal —— 中间层多态

// 普通写法拆成三步
// 第一步：声明引用变量（造一个 Dog 遥控器，按钮只有 Dog 能响应的）
Dog myDog;
// 第二步：创建对象（在堆上造一台 Dog 电视）
myDog = new Dog();
// 第三步其实合并在上面这行：把电视频率写进遥控器

// 也可以一行写完，含义完全相同：
Dog myDog2 = new Dog();       // 引用类型 Dog，对象类型 Dog，两边一样

// 多态写法：只改第一步的引用类型
Animal myAnimal = new Dog();  // 引用类型 Animal，对象类型 Dog，两边不同
// 为什么合法：Dog IS-A Animal
// 为什么安全：Animal 有的方法 Dog 一定有（继承或覆盖）
// 变的是什么：遥控器从 Dog 版换成 Animal 版，按钮变少
// 不变的是什么：堆上那个对象仍然是完整的 Dog

// myAnimal.bark();  // 编译失败：Animal 遥控器没有 bark 这个按钮

Animal[] animals = new Animal[5];   // 建的是数组对象，不是 5 个 Animal 实例
animals[0] = new Dog();             // 每个槽位装一个子类对象的引用
animals[1] = new Cat();
animals[2] = new Wolf();
animals[3] = new Hippo();
animals[4] = new Lion();

for (Animal animal : animals) {     // animal 的编译期类型是 Animal
    animal.eat();                   // 同一行代码，五轮跑五个不同实现
    animal.roam();                  // 狗跑 Canine 群居版，猫跑 Feline 独行版
}

// 逐轮落点（最低者获胜）：
// Dog   → eat 跑 Dog，   roam 跑 Canine
// Cat   → eat 跑 Cat，   roam 跑 Feline
// Wolf  → eat 跑 Wolf，  roam 跑 Canine
// Hippo → eat 跑 Hippo， roam 跑 Animal
// Lion  → eat 跑 Lion，  roam 跑 Feline

// animal.sleep() 合法但五轮都跑 Animal 通用版（没人覆盖）
// animal.fetch() 编译失败：Animal 没有这个方法

class Vet {
    // 多态参数：声明成父类型 Animal，能接任何 Animal 子类
    public void giveShot(Animal a) {
        System.out.println("打针...");
        a.makeNoise();   // 编译期查 Animal 有 makeNoise，运行期跑实参对象的版本
    }
}

class PetOwner {
    public void start() {
        Vet vet = new Vet();
        Dog dog = new Dog();
        Hippo hippo = new Hippo();
        vet.giveShot(dog);     // Dog IS-A Animal，跑 Dog 的 makeNoise（汪汪）
        vet.giveShot(hippo);   // Hippo IS-A Animal，跑 Hippo 的 makeNoise（哼哼）
        // 明天新增 Penguin，vet.giveShot(new Penguin()) 照样工作，Vet 一个字不改
    }
}

// 多态返回类型：声明返回 Animal，实际返回任意子类
class Zoo {
    public Animal getAnimal() {
        return new Dog();      // Dog IS-A Animal，合法；明天改成 new Cat() 调用方不变
    }
}
Animal a = new Zoo().getAnimal();   // 拿到 Animal 引用，背后是 Dog

// 论证演示：核心方法对「未来才知道」的类型照样工作
class Vet {
    public void giveShot(Animal a) {   // 只依赖 Animal 协议
        a.makeNoise();
    }
}

// 今天的类型
class Dog extends Animal {
    public void makeNoise() { System.out.println("汪汪"); }
}

// 三个月后别人新增的类型，Vet 完全不知道它存在
class Penguin extends Animal {
    @Override public void makeNoise() { System.out.println("嘎嘎"); }
}

// 五步论证：
// 1. Penguin IS-A Animal → 实参能传给形参（编译期）
// 2. Animal 有 makeNoise → 方法体合法（编译期）
// 3. 运行期 JVM 看对象是 Penguin → 跑 Penguin 的嘎嘎（运行期）
// 4. Penguin 必有 makeNoise → 继承或覆盖，不会没有
// 5. 结论：Vet 一字不改就支持了新类型
vet.giveShot(new Penguin());   // 打印嘎嘎

