class PackagePrivateClass { }              // 没有 public，包外看不见

// 2. final 类：继承线的终点
final class StringLike { }                 // 谁也不能 extends
// class Bad extends StringLike { }         // 编译失败

// 3. 构造器全 private：外部造不出对象，也造不出子类
class NoSubclass {
    private NoSubclass() { }
}

// final 方法：只封一个方法，类仍可继承
class Parent {
    final void fixed() { }                 // 不可覆盖
    void flexible() { }                    // 可以覆盖
}
class Child extends Parent {
    @Override void flexible() { }
    // void fixed() { }  // 编译失败：final 方法不能覆盖
}

