public class Overloads {
    String uniqueID;

    // 重载 1：两个 int，返回 int
    public int addNums(int a, int b) { return a + b; }

    // 重载 2：两个 double，返回 double —— 参数不同，返回类型可任意改
    public double addNums(double a, double b) { return a + b; }

    public void setUniqueID(String theID) {
        uniqueID = theID;                 // 假设这里有很多校验代码
    }

    // 重载 3：参数是 int，内部转成 String 后调用上面的版本
    public void setUniqueID(int ssNumber) {
        String numString = "" + ssNumber; // int 转 String 的常见技巧
        setUniqueID(numString);
    }
}

// 编译期重载解析（不是多态）：
// x.addNums(1, 2)     → 选 addNums(int,int)
// x.addNums(1.0, 2.0) → 选 addNums(double,double)

// 三条重载规则：
// 1. 返回类型可以不同（只要参数列表不同）
// 2. 不能只改返回类型（参数必须变，否则编译失败）
// 3. 可见性可以任意方向改（不像覆盖不能收紧）

class A {
    int ivar = 7;                                   // 变量不覆盖，只有这一份
    void m1() { System.out.print("A's m1, "); }
    void m2() { System.out.print("A's m2, "); }
    void m3() { System.out.print("A's m3, "); }
}
class B extends A {
    void m1() { System.out.print("B's m1, "); }      // 覆盖 m1
}
class C extends B {
    void m3() { System.out.print("C's m3, " + (ivar + 6)); }  // 覆盖 m3，ivar=7 → 13
}

A a = new A();    // 声明 A，对象 A
B b = new B();    // 声明 B，对象 B
C c = new C();    // 声明 C，对象 C
A a2 = new C();   // 声明 A，对象 C —— 多态引用！

// a2.m1(); → B's m1, （对象 C 往上找，B 的实现最低）
// a2.m2(); → A's m2, （C、B 都没有，到 A）
// a2.m3(); → C's m3, 13（C 的实现，ivar 是继承的 7）
// 结论：a2 系列输出 B's m1, A's m2, C's m3, 13
// 陷阱：a2 是 A 引用 ≠ 跑 A 的方法；ivar 不覆盖，只有 7 这一份

public class MonsterTestDrive {
