// Pool Puzzle 完整答案
public class Boat {
    private int length;                 // 私有，子类碰不到
    public void setLength(int len) {
        length = len;                   // 通过公开方法间接写
    }
    public int getLength() {
        return length;                  // 通过公开方法间接读
    }
    public void move() {
        System.out.print("drift ");     // 默认行为：漂流
    }
}

public class Rowboat extends Boat {
    public void rowTheBoat() {
        System.out.print("stroke natasha");
    }
    // 不覆盖 move → 继承 Boat 的 drift
}

public class Sailboat extends Boat {
    @Override
    public void move() {
        System.out.print("hoist sail ");  // 覆盖：升帆
    }
}

public class TestBoats {
    public static void main(String[] args) {
        Boat b1 = new Boat();
        Sailboat b2 = new Sailboat();
        Rowboat b3 = new Rowboat();
        b2.setLength(32);
        b1.move();     // drift  （Boat 自己）
        b3.move();     // drift  （Rowboat 没覆盖，继承 Boat）
        b2.move();     // hoist sail（Sailboat 覆盖了）
    }
}
// 输出：drift drift hoist sail

// 本章两个主角：抽象类与接口（先建立印象，后面逐节讲透）

// 抽象类：不能 new，但能当引用类型、能被继承
public abstract class Animal {
    public abstract void makeNoise();   // 抽象方法：没有方法体
    public void sleep() {               // 具体方法：有实现
        System.out.println("睡觉");
    }
}
// Animal a = new Animal();  // 编译错误：抽象类不能实例化
Animal a = new Dog();        // 但能声明引用指向子类对象

// 接口：100% 抽象的「能力合同」
public interface Pet {
    void beFriendly();       // 隐式 public abstract
    void play();
}
// 类用 implements 实现接口，同时还能 extends 一个类
public class Dog extends Animal implements Pet {
    public void makeNoise() { System.out.println("汪汪"); }
    public void beFriendly() { System.out.println("摇尾巴"); }
    public void play() { System.out.println("追球"); }
}
// Dog 既是 Animal（身份），又是 Pet（角色）

