Animal anim = new Animal();    // Animal 引用 → Animal 对象：类型相同，但……

// 一个 Animal 对象到底长什么样？
// 什么形状？什么颜色？几条腿？—— 都没有答案
// 就像《星际迷航》传送事故：缓冲区出错，传上来个四不像

// 实例化 instantiation：用 new 根据类造出一个真实对象的过程
// 类 = 图纸，对象 = 按图纸盖的房子
// Animal 这张「图纸」太抽象，不该拿来直接盖房子

// 解法：把 Animal 标成 abstract
// 之后 new Animal() 会被编译器拦下，但 Animal 引用照样能用
Animal a = new Dog();          // ✓ 抽象引用 + 具体对象
// Animal a2 = new Animal();   // ✗ 编译错误

abstract public class Canine extends Animal {
    public void roam() { }
}

public class MakeCanine {
    public void go() {
        Canine c;            // ✓ 可以：抽象类做引用类型
        c = new Dog();       // ✓ 可以：子类对象赋给父类引用（多态）
        // c = new Canine(); // ✗ 编译错误：Canine is abstract; cannot be instantiated
        c.roam();
    }
}

// 三句赋值的含义：
// Canine c;        → 抽象引用能用
// c = new Dog();   → 抽象引用能指向具体子类对象
// c = new Canine();// → 抽象类不能 new，编译器把关

// 抽象类的边界自测：
// abstract class A { }
// A a = new A();        ✗ 不能实例化
// A a;                  ✓ 声明引用
// A a = new B();        ✓ B extends A 且具体
// 抽象类可有实例变量、具体方法、构造器、静态成员
// 抽象类不能与 final 同时修饰（一个要被继承，一个禁止继承）

// 抽象 vs 具体：判断标准是「程序要不要区分这个类的不同种类」

// 动物树：三个概念层标 abstract，六个具体动物保持 concrete
public abstract class Animal { }        // 抽象：不 new「一般动物」
public abstract class Canine extends Animal { }
public abstract class Feline extends Animal { }
public class Dog extends Canine { }     // 具体：真有狗
public class Hippo extends Animal { }   // 具体：真有河马

// GUI 库：Component 是抽象概念，JButton 才是能摆上屏幕的东西
// abstract Component → concrete JButton / JTextArea / JScrollBar

// Tree 的双重身份（判断取决于程序需求）：
// 苗圃程序：Tree 抽象（要区分 Oak 与 Aspen 卖苗）
// 高尔夫模拟：Tree 具体（只是 Obstacle，不区分树种）

// Customer：收银系统里具体；CRM 里抽象（VIP/普通/潜在客户行为不同）
// Book：借阅系统里具体；出版社系统里抽象（小说/教材/画册流程不同）

public abstract class Animal {
    // 抽象方法：没有方法体，分号结尾
    public abstract void makeNoise();
    public abstract void eat();

    // 具体方法：有方法体，子类可直接继承
    public void sleep() {
        System.out.println("通用睡觉");
    }
    public void roam() {
        System.out.println("通用游荡");
    }
}

// 对应规则：
// ① 有抽象方法的类必须标 abstract
// ② 抽象方法不能有方法体：public abstract void eat() { } 是错的
// ③ 抽象类可混合抽象方法与具体方法
// ④ private abstract void m() 非法（子类无法覆盖看不见的方法）

// 为什么需要：
// 声明「所有 Animal 子类型都有 makeNoise/eat」，但想不出通用实现
// → 为多态定义协议：Vet.giveShot(Animal a) 里可放心调 a.makeNoise()
// → 不用为 Lion、Wolf、Hippo 各写一个 giveShot 重载

public abstract class Animal {
    public abstract void makeNoise();   // 欠实现
    public abstract void eat();         // 欠实现
}

// 抽象子类可以「接一部分活」，把责任往下推
public abstract class Canine extends Animal {
    @Override public void eat() {       // Canine 实现了 eat，Dog 不用再写
        System.out.println("犬科通用吃法");
    }
    // makeNoise 还没实现，继续欠着
}

// 第一个具体类必须补齐所有剩下的抽象方法
public class Dog extends Canine {
    @Override public void makeNoise() { System.out.println("汪汪"); }  // 必须写
    // eat 已由 Canine 实现，不必再写
}

// 如果 Dog 忘了写 makeNoise，编译报错：
// Dog is not abstract and does not override abstract method makeNoise() in Animal

// 踢皮球规则：
// 抽象类可以把实现责任继续往下推（保持 abstract）
// 第一个具体类必须实现继承链上所有未实现的抽象方法
// 实现 = 写签名匹配、带方法体的方法（和覆盖动作一样）

// 第一版：只能装狗
public class MyDogList {
    private Dog[] dogs = new Dog[5];
    private int nextIndex = 0;
    public void add(Dog d) {
        if (nextIndex < dogs.length) {
            dogs[nextIndex] = d;
            System.out.println("Dog added at " + nextIndex);
            nextIndex++;
        }
    }
}

// 第二/三版：把类型从 Dog 换成 Animal，逻辑一字不改
public class MyAnimalList {
    private Animal[] animals = new Animal[5];   // 建的是数组对象，不是 Animal 实例
    private int nextIndex = 0;
    public void add(Animal a) {                // 多态参数
        if (nextIndex < animals.length) {
            animals[nextIndex] = a;
            System.out.println("Animal added at " + nextIndex);
            nextIndex++;
        }
    }
}

