// 接口来救场！
public interface Pet {
    public abstract void beFriendly();   // 抽象方法：分号结尾，无方法体
    public abstract void play();
}

public class Dog extends Canine implements Pet {
    public void beFriendly() { System.out.println("摇尾巴"); }  // 实现：花括号
    public void play() { System.out.println("追球"); }
    public void roam() { }   // 从动物继承的行为照旧
    public void eat() { }
}
// Dog IS-A Animal（通过继承） 且 Dog IS-A Pet（通过实现接口）

// 一句话对照三条需求：
// ① 不污染：Hippo 不 implements Pet，就没有宠物方法 ✓
// ② 有支撑的协议：编译器检查 implements Pet 的类必须实现全部方法 ✓
// ③ 多态：playWithPet(Pet p) 统一处理，新增宠物 implements Pet 即可 ✓

// 绕开菱形：接口方法全抽象、无实例变量 → 子类自己实现 → 无歧义

// 接口的真正威力：跨继承树 + 多实现
public interface Pet {
    void beFriendly();
    void play();
}

// 真狗：来自动物继承树
public class Dog extends Animal implements Pet {
    public void beFriendly() { }
