// 关键规则：实线继承身份、虚线实现角色、一个父类多个接口

// Pool Puzzle 完整答案
interface Nose {
    public int iMethod();              // 抽象方法，分号结尾
}

abstract class Picasso implements Nose {
    public int iMethod() { return 7; } // 默认实现返回 7
}

class Acts extends Picasso {
    @Override public int iMethod() { return 5; }  // 覆盖返回 5
}

class Clowns extends Picasso { }       // 不覆盖，用 Picasso 的 7

public class Of76 extends Clowns {
    public static void main(String[] args) {
        Nose[] i = new Nose[3];         // 接口当数组类型！
        i[0] = new Acts();
        i[1] = new Clowns();
        i[2] = new Of76();
        for (int x = 0; x < 3; x++) {
            System.out.println(i[x].iMethod() + " " + i[x].getClass());
        }
    }
}
// 输出：
// 5 class Acts     （Acts 覆盖 iMethod 返回 5）
// 7 class Clowns   （没覆盖，用 Picasso 的 7）
// 7 class Of76     （Of76→Clowns→Picasso，没覆盖，返回 7）
// getClass 来自 Object，任何引用（含接口引用）都能调

// 返回码风格: 每一步都要检查
int step1 = doStep1();
if (step1 < 0) { logger.error("step1 failed"); return -1; }
int step2 = doStep2(step1);
if (step2 < 0) { logger.error("step2 failed"); return -2; }
return doStep3(step2);

// 异常风格: 只写正常路径
public int run() throws StepException {
  int a = doStep1();
  int b = doStep2(a);
  return doStep3(b);
}

import java.io.*;

public class FamilyDemo {
  static void throwError() {
    throw new StackOverflowError("栈溢出");
  }

  static void throwChecked() throws IOException {
    throw new IOException("文件读取失败");
  }

  static void throwUnchecked() {
    throw new IllegalArgumentException("参数非法");
  }

  public static void main(String[] args) throws IOException {
    try { throwError(); } catch (Error e) { System.out.println("捕获 Error: " + e); }
    throwChecked();      // 必须声明或捕获
    throwUnchecked();    // 无需声明
  }
}

