// 这段代码能编译、能运行，但按钮为什么又窄又高、为什么占满整个右侧？
// 答案不在代码里，而在 BorderLayout 的「尺寸政策」里——这正是本章要讲的东西。

// 组件与容器的典型搭配，以及组件的嵌套
JFrame frame = new JFrame();                          // 顶层容器（窗口）
JPanel panel = new JPanel();                          // 背景容器（面板），默认布局 FlowLayout
JButton button = new JButton("click me");             // 交互组件（按钮）
JCheckBox check = new JCheckBox("Goes to 11");        // 交互组件（复选框）
JTextField field = new JTextField(20);                // 交互组件（文本框）

// 惯例：把交互组件 add 进背景容器
panel.add(button);
panel.add(check);
panel.add(field);

// 再把装好的 panel 作为一个整体 add 进 frame
frame.getContentPane().add(panel);
frame.setSize(300, 300);
frame.setVisible(true);

// 技术上你甚至可以把 panel 塞进 button（button.add(panel) 能编译），
// 但这很怪，也不会拿到任何「可用性奖」——别这么干。

JPanel panelA = new JPanel();
JPanel panelB = new JPanel();
panelB.add(new JButton("button 1"));   // B 的布局管理器管这三个按钮
panelB.add(new JButton("button 2"));
panelB.add(new JButton("button 3"));
panelA.add(panelB);                     // A 的布局管理器只管 panelB 这个整体

// 层级关系（从外到内）：
//   panelA 的布局管理器 -> 管 panelB 的位置和大小
//   panelB 的布局管理器 -> 管三个按钮的位置和大小
//   panelA 的布局管理器 对三个按钮 完全没有发言权
// 想改按钮排列？去找直接装按钮的 panelB，别去找 panelA。

// 用一段代码看 preferred size 是如何「传导」的
JFrame frame = new JFrame();
JPanel panel = new JPanel();                    // 默认 FlowLayout

JButton b1 = new JButton("hi");                 // 字短 -> preferred 宽度小
JButton b2 = new JButton("a much longer label");// 字长 -> preferred 宽度大
panel.add(b1);
panel.add(b2);

frame.getContentPane().add(BorderLayout.EAST, panel);
frame.pack();                                   // pack 会按整条链算出窗口该多大
frame.setVisible(true);

// 传导链：按钮文字 -> 按钮 preferred size -> panel preferred size
//         -> frame 按 EAST 区政策给 panel 宽度 -> 最终界面
// 若把 b2 文字改长，整条链重算，panel 和窗口都会跟着变宽。

import javax.swing.*;
import java.awt.*;          // BorderLayout 住在这个包里，别漏了这行 import

public class Button1 {
  public static void main(String[] args) {
    new Button1().go();
  }
  public void go() {
    JFrame frame = new JFrame();
    JButton button = new JButton("click me");
    // 双参数 add：第一个参数是区域常量，第二个是组件
    frame.getContentPane().add(BorderLayout.EAST, button);
    frame.setSize(200, 200);
    frame.setVisible(true);
  }
}
// 结果：按钮宽度 = 文字的 preferred 宽度（窄窄一条），
//       高度 = 整个 frame 的高度（撑满右侧）。

public void go() {
  JFrame frame = new JFrame();

  // 实验一：north 区按钮拿到 preferred 高度、宽度拉满
  JButton north = new JButton("There is no spoon...");
  frame.getContentPane().add(BorderLayout.NORTH, north);

  // 实验二：换大字体 -> preferred 高度变大 -> north 区变高
  JButton big = new JButton("Click This!");
  big.setFont(new Font("serif", Font.BOLD, 28));
  frame.getContentPane().add(BorderLayout.SOUTH, big);

  // 实验三：五区全满
  frame.getContentPane().add(BorderLayout.EAST,  new JButton("East"));
  frame.getContentPane().add(BorderLayout.WEST,  new JButton("West"));
  frame.getContentPane().add(BorderLayout.CENTER, new JButton("Center"));

  frame.setSize(300, 300);
  frame.setVisible(true);
}
// 口诀：东西拿 preferred 宽度、高度拉满；南北拿 preferred 高度、宽度拉满；
//       center 拿剩余空间。换字体 = 改 preferred size = 间接改布局。

public void go() {
  JFrame frame = new JFrame();
  JPanel panel = new JPanel();                  // 默认 FlowLayout
  panel.setBackground(Color.darkGray);         // 涂灰便于观察边界

  JButton button    = new JButton("shock me");
  JButton buttonTwo = new JButton("bliss");
  JButton buttonThree = new JButton("huh?");
  panel.add(button);                            // 从左到右排
  panel.add(buttonTwo);                         // 空间够就同一行
  panel.add(buttonThree);                       // 放不下就自动换行

  frame.getContentPane().add(BorderLayout.EAST, panel);
  frame.setSize(250, 200);
  frame.setVisible(true);
}
// FlowLayout：横排、放不下换行、宽高都给 preferred size。
// panel 加按钮会横向扩张，因为它的 preferred size 变大了。

public void go() {
  JFrame frame = new JFrame();
  JPanel panel = new JPanel();
  panel.setBackground(Color.darkGray);

  // 关键一步：把默认 FlowLayout 换成纵向 BoxLayout
  // 构造器第一个参数是「被布局的面板自己」，第二个是轴向
  panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));

  JButton button    = new JButton("shock me");
  JButton buttonTwo = new JButton("bliss");
  panel.add(button);        // 上下排列，不再并排
  panel.add(buttonTwo);

  frame.getContentPane().add(BorderLayout.EAST, panel);
  frame.setSize(250, 200);
  frame.setVisible(true);
}

// Box 是便捷写法：等价于建了个已设好 Y_AXIS BoxLayout 的 JPanel
Box buttonBox = new Box(BoxLayout.Y_AXIS);

// 方式一：默认写法 —— 组件加在 frame 的内容面板上
JFrame frame = new JFrame();
frame.getContentPane().add(BorderLayout.CENTER, someComponent);

// 方式二：自建 panel，搭好整个界面，再把它设为内容面板
JPanel myPanel = new JPanel();
myPanel.setLayout(new BoxLayout(myPanel, BoxLayout.Y_AXIS));
myPanel.add(new JButton("one"));
myPanel.add(new JButton("two"));
frame.setContentPane(myPanel);      // 用自定义 panel 换掉默认 content pane

// 方式三（Java 5+ 便利写法，内部仍是转发到 content pane）
frame.add(someComponent);
// 以上三种本质相同：组件最终都住在「内容面板」这块纯 Java 玻璃上。

// 想改组件尺寸：setSize 没用，改 preferred size 才有用
JButton b = new JButton("hi");
b.setSize(300, 100);   // 布局管理器忽略它，按钮尺寸不变
b.setFont(new Font("serif", Font.BOLD, 28));   // 改内容 -> preferred size 变大 -> 有效
b.setPreferredSize(new Dimension(200, 80));     // 直接设首选尺寸 -> 布局会尊重

// 关掉布局管理器手动定位（几乎总不推荐）
JPanel p = new JPanel();
p.setLayout(null);                 // 关掉布局
JButton manual = new JButton("x");
manual.setBounds(20, 30, 100, 40); // x, y, 宽, 高，自己算坐标
p.add(manual);
// 代价：窗口一缩放、换平台/观感，写死的坐标就全乱。

JTextField field = new JTextField(20);      // 20 是列数（决定 preferred 宽度），不是像素

// 1) 取内容
String typed = field.getText();

// 2) 设内容 / 清空
field.setText("whatever");
field.setText("");

// 3) 用户按回车时触发 ActionEvent（和按钮同一套事件模型）
field.addActionListener(e -> {
  System.out.println("提交：" + field.getText());
  field.setText("");        // 清空
  field.requestFocus();     // 光标回来，方便继续输入
});

// 4) 选中全部文字（输错了让用户一打字就覆盖）
field.selectAll();

// 也可带初始文字构造：new JTextField("Your name")
// 想监听每个键：field.addKeyListener(...)，但多数场景用回车监听就够。

// JScrollPane 标准五步模板（以 JTextArea 为例）
// 1) 建内容组件
JTextArea text = new JTextArea(10, 20);
// 2) 配置内容
text.setLineWrap(true);
// 3) 把内容交给滚动面板的构造器
JScrollPane scroller = new JScrollPane(text);
// 4) 设滚动条策略
scroller.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_ALWAYS);
scroller.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
