private void setUpMidi() {
  try {
    sequencer = MidiSystem.getSequencer();       // 工厂方法拿音序器（接口 -> 具体实现）
    sequencer.open();                            // 打开设备，准备播放
    sequence = new Sequence(Sequence.PPQ, 4);    // PPQ 分辨率，每四分音符 4 tick
    track = sequence.createTrack();              // 建一条轨道
    sequencer.setTempoInBPM(120);                // 每分钟 120 拍
  } catch (Exception e) {
    e.printStackTrace();                         // 受检异常必须处理
  }
}

private void changeTempo(float tempoMultiplier) {
  float tempoFactor = sequencer.getTempoFactor();          // 读当前倍率
  sequencer.setTempoFactor(tempoFactor * tempoMultiplier);  // 读-改-写：累积调整
}
// 默认 factor=1.0；Tempo Up 传 1.03f（快 3%），Down 传 0.97f（慢 3%）。
// factor 是音序器级属性，循环各轮自动保持新速度。

private void buildTrackAndStart() {
  int[] trackList;
  sequence.deleteTrack(track);              // 丢掉旧轨道
  track = sequence.createTrack();           // 建全新轨道，保证每次干净

  for (int i = 0; i < 16; i++) {            // 外层：16 行 = 16 个乐器
    trackList = new int[16];                // 这个乐器横跨 16 拍的发声清单
    int key = instruments[i];               // 该乐器的 MIDI 音符编号
    for (int j = 0; j < 16; j++) {          // 内层：16 拍 = 16 列
      JCheckBox jc = checkboxList.get(j + 16 * i);  // 行优先下标 = 行号*列数+列号
      trackList[j] = jc.isSelected() ? key : 0;     // 勾了放 key，没勾放 0（哨兵）
    }
    // 下半节：makeTracks(trackList) 把这一行变成 MIDI 事件……
  }
  // ……
}

// j + 16*i 详解：GridLayout(16,16) 与 add 顺序都是行优先，
// 第 i 行第 j 列 -> 一维下标 i*16+j。第 0 行 0~15，第 1 行 16~31……

private void buildTrackAndStart() {
  int[] trackList;
  sequence.deleteTrack(track);              // 丢掉旧轨道
  track = sequence.createTrack();           // 建全新轨道

  for (int i = 0; i < 16; i++) {            // 16 行 = 16 个乐器
    trackList = new int[16];
    int key = instruments[i];
    for (int j = 0; j < 16; j++) {          // 16 拍
      JCheckBox jc = checkboxList.get(j + 16 * i);
      trackList[j] = jc.isSelected() ? key : 0;
    }
    makeTracks(trackList);                  // 这一行 -> MIDI 事件
    track.add(makeEvent(CONTROL_CHANGE, 1, 127, 0, 16)); // 第 16 拍占位，保证循环走满 16 拍
  }
  track.add(makeEvent(PROGRAM_CHANGE, 9, 1, 0, 15));     // 切到正确的鼓组音色
  try {
    sequencer.setSequence(sequence);
    sequencer.setLoopCount(sequencer.LOOP_CONTINUOUSLY);  // 无限循环
    sequencer.setTempoInBPM(120);
    sequencer.start();                                   // 开播！
  } catch (Exception e) {
    e.printStackTrace();
  }
}

private void makeTracks(int[] list) {
  for (int i = 0; i < 16; i++) {
    int key = list[i];
    if (key != 0) {                          // 0 = 这一拍不响
      track.add(makeEvent(NOTE_ON, 9, key, 100, i));      // 第 i 拍开始
      track.add(makeEvent(NOTE_OFF, 9, key, 100, i + 1)); // 下一拍停止，持续一拍
    }
  }
}
// makeEvent(cmd, chnl, one, two, tick) 是第 13 章工具：建 ShortMessage + 包 MidiEvent。

// BeatBox 完整代码清单（第 13/14/15 章知识总汇合）
import javax.sound.midi.*;
import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import static javax.sound.midi.ShortMessage.*;

public class BeatBox {
  private ArrayList<JCheckBox> checkboxList;
  private Sequencer sequencer;
  private Sequence sequence;
  private Track track;
  String[] instrumentNames = {"Bass Drum", "Closed Hi-Hat", "Open Hi-Hat",
      "Acoustic Snare", "Crash Cymbal", "Hand Clap", "High Tom", "Hi Bongo",
      "Maracas", "Whistle", "Low Conga", "Cowbell", "Vibraslap",
      "Low-mid Tom", "High Agogo", "Open Hi Conga"};
  int[] instruments = {35, 42, 46, 38, 49, 39, 50, 60, 70, 72, 64, 56, 58, 47, 67, 63};

  public static void main(String[] args) { new BeatBox().buildGUI(); }

  public void buildGUI() {
    JFrame frame = new JFrame("Cyber BeatBox");
    frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
    JPanel background = new JPanel(new BorderLayout());
    background.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
    Box buttonBox = new Box(BoxLayout.Y_AXIS);
    JButton start = new JButton("Start");
    start.addActionListener(e -> buildTrackAndStart());
    buttonBox.add(start);
    JButton stop = new JButton("Stop");
    stop.addActionListener(e -> sequencer.stop());
    buttonBox.add(stop);
    JButton upTempo = new JButton("Tempo Up");
    upTempo.addActionListener(e -> changeTempo(1.03f));
    buttonBox.add(upTempo);
    JButton downTempo = new JButton("Tempo Down");
    downTempo.addActionListener(e -> changeTempo(0.97f));
    buttonBox.add(downTempo);
    Box nameBox = new Box(BoxLayout.Y_AXIS);
    for (String name : instrumentNames) {
      JLabel label = new JLabel(name);
      label.setBorder(BorderFactory.createEmptyBorder(4, 1, 4, 1));
      nameBox.add(label);
    }
    background.add(BorderLayout.EAST, buttonBox);
    background.add(BorderLayout.WEST, nameBox);
    frame.getContentPane().add(background);
    GridLayout grid = new GridLayout(16, 16);
    grid.setVgap(1);
    grid.setHgap(2);
    JPanel mainPanel = new JPanel(grid);
    background.add(BorderLayout.CENTER, mainPanel);
    checkboxList = new ArrayList<>();
    for (int i = 0; i < 256; i++) {
      JCheckBox c = new JCheckBox();
      c.setSelected(false);
      checkboxList.add(c);
      mainPanel.add(c);
    }
    setUpMidi();
    frame.setBounds(50, 50, 300, 300);
    frame.pack();
    frame.setVisible(true);
  }

  private void setUpMidi() {
    try {
      sequencer = MidiSystem.getSequencer();
      sequencer.open();
      sequence = new Sequence(Sequence.PPQ, 4);
      track = sequence.createTrack();
      sequencer.setTempoInBPM(120);
    } catch (Exception e) { e.printStackTrace(); }
  }

  private void buildTrackAndStart() {
    int[] trackList;
    sequence.deleteTrack(track);
    track = sequence.createTrack();
    for (int i = 0; i < 16; i++) {
      trackList = new int[16];
      int key = instruments[i];
      for (int j = 0; j < 16; j++) {
        JCheckBox jc = checkboxList.get(j + 16 * i);
        trackList[j] = jc.isSelected() ? key : 0;
      }
      makeTracks(trackList);
      track.add(makeEvent(CONTROL_CHANGE, 1, 127, 0, 16));
    }
    track.add(makeEvent(PROGRAM_CHANGE, 9, 1, 0, 15));
    try {
      sequencer.setSequence(sequence);
      sequencer.setLoopCount(sequencer.LOOP_CONTINUOUSLY);
      sequencer.setTempoInBPM(120);
      sequencer.start();
    } catch (Exception e) { e.printStackTrace(); }
  }

  private void changeTempo(float tempoMultiplier) {
    float tempoFactor = sequencer.getTempoFactor();
    sequencer.setTempoFactor(tempoFactor * tempoMultiplier);
  }

  private void makeTracks(int[] list) {
    for (int i = 0; i < 16; i++) {
      int key = list[i];
      if (key != 0) {
        track.add(makeEvent(NOTE_ON, 9, key, 100, i));
        track.add(makeEvent(NOTE_OFF, 9, key, 100, i + 1));
      }
    }
  }

  public static MidiEvent makeEvent(int cmd, int chnl, int one, int two, int tick) {
    MidiEvent event = null;
    try {
      ShortMessage msg = new ShortMessage();
      msg.setMessage(cmd, chnl, one, two);
      event = new MidiEvent(msg, tick);
    } catch (Exception e) { e.printStackTrace(); }
    return event;
  }
}

