sealed interface Shape permits Circle, Square, Rect { }

record Circle(double r) implements Shape { }
record Square(double side) implements Shape { }
final class Rect implements Shape {           // 子类型必须声明 final / sealed / non-sealed
    final double w, h;
    Rect(double w, double h) { this.w = w; this.h = h; }
}

double area(Shape s) {
    return switch (s) {
        case Circle c -> Math.PI * c.r() * c.r();
        case Square q -> q.side() * q.side();
        case Rect r -> r.w * r.h;
    };   // 不需要 default，编译器知道只有这三种
}

sealed interface Expr permits Num, Add, Mul { }
record Num(int v) implements Expr { }
record Add(Expr l, Expr r) implements Expr { }
record Mul(Expr l, Expr r) implements Expr { }

int eval(Expr e) {
    return switch (e) {
        case Num(int v) -> v;                                   // 记录模式拆解
        case Add(Expr l, Expr r) -> eval(l) + eval(r);
        case Mul(Expr l, Expr r) -> eval(l) * eval(r);
        case null -> throw new IllegalArgumentException("null");
    };
}

// 守卫条件
String describe(Object o) {
    return switch (o) {
        case Integer i when i > 100 -> "大数";
        case Integer i -> "小数";
        case String s when s.isEmpty() -> "空串";
        case String s -> "字符串";
        default -> "其他";
    };
}

