// 6-10) bears[0..4].hunny              ← 循环五只熊各有引用
// 11) kit.honey（kit=null 后仍作为 raccoon.rk.honey 存在）← 最易漏
// 12) raccoon.rh
//
// 注意：bees.beeHoney 指向的是数组 ha，raccoon.rk 指向 Kit 对象，
//       它们是通往 H 的路径中转，不是直接引用 H，不计入 12 根。

// Collections 和 Math 一样是工具类：构造器私有、方法全静态
import java.util.*;
List<String> list = new ArrayList<>(List.of("c", "a", "b"));
Collections.sort(list);        // 静态方法，类名调用
list.sort(String::compareTo);  // Java 8 起的实例方法版，效果相同

// List.of 工厂方法也是静态，且返回不可变集合
List<String> fixed = List.of("a", "b", "c");
// fixed.add("d");  // UnsupportedOperationException：不可变

// 按 BPM 升序：a - b 的符号恰好符合 compare 契约
songList.sort((one, two) -> one.getBpm() - two.getBpm());

// 按歌名降序：对调 compareTo 的操作数 = 把符号翻转
songList.sort((one, two) -> two.getTitle().compareTo(one.getTitle()));

// 输出验证
// 按 BPM 升序：[50 ways, havana, $10, somersault, cassidy, Cassidy]  (102,105,140,147,158,158)
// 按歌名降序：[somersault, havana, cassidy, Cassidy, 50 ways, $10]

// 更稳妥的数值比较（避免溢出）：
// songList.sort((one, two) -> Integer.compare(one.getBpm(), two.getBpm()));

public void go() {
  JFrame frame = new JFrame();
  frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
  MyDrawP drawP = new MyDrawP();
  frame.getContentPane().add(drawP);
  frame.setSize(500, 270);
  frame.setVisible(true);
  for (int i = 0; i < 124; i++, y++, x++) {
    x++;
    drawP.repaint();
    try { TimeUnit.MILLISECONDS.sleep(50); } catch (Exception ex) { }
  }
}
class MyDrawP extends JPanel {
  public void paintComponent(Graphics g) {
    g.setColor(Color.white);
    g.fillRect(0, 0, 500, 250);
    g.setColor(Color.blue);
    g.fillRect(x, y, 500 - x * 2, 250 - y * 2);
  }
}

// 布局选择决策树（今后写 Swing 界面的检查清单）
// 1) 几个组件？怎么排？
//    一个 -> 默认布局 / 单参数 add（落 center）
//    分区 -> BorderLayout（东西南北中，每区一个）
//    横排换行 -> FlowLayout（panel 默认）
//    竖排 -> BoxLayout(Y_AXIS) 或 Box
//    矩阵 -> GridLayout（等大，忽略 preferred size）
//    复杂 -> 嵌套：外层 BorderLayout，内层各自布局（BeatBox 模式）
// 2) 尺寸不对？查"谁的布局、什么政策、尊重 preferred size 多少"
//    setSize 无效 -> 改内容或 setPreferredSize
// 3) 看不见？查 setVisible / 是否 add 到 content pane / JScrollPane /
//    同区域被顶掉 / 组件是不是压根没被 add（孤儿 panel）
// 4) 界面卡住？EDT 被耗时操作堵住 -> 后台线程 + invokeLater + Timer

// 保存：把 256 个复选框状态压成一个 boolean 数组序列化出去
private void writeFile() {
  boolean[] checkboxState = new boolean[256];
  for (int i = 0; i < 256; i++) {
    if (checkboxList.get(i).isSelected()) checkboxState[i] = true;
  }
  try (ObjectOutputStream os =
         new ObjectOutputStream(new FileOutputStream("Checkbox.ser"))) {
    os.writeObject(checkboxState);
  } catch (IOException e) { e.printStackTrace(); }
}

// 还原：读回来强转成 boolean[]，再逐个设置复选框
private void readFile() {
  boolean[] checkboxState = null;
  try (ObjectInputStream is =
         new ObjectInputStream(new FileInputStream("Checkbox.ser"))) {
    checkboxState = (boolean[]) is.readObject();
  } catch (Exception e) { e.printStackTrace(); }
  for (int i = 0; i < 256; i++) checkboxList.get(i).setSelected(checkboxState[i]);
  sequencer.stop();
  buildTrackAndStart();
}

