// 单一上界
static <T extends Number> double sum(List<T> xs) {
  double s = 0;
  for (T x : xs) s += x.doubleValue();   // 能调 Number 的方法
  return s;
}

// 多重上界：擦除取第一个，即 Number
static <T extends Number & Comparable<T>> T max(List<T> xs) {
  T best = xs.get(0);
  for (T x : xs) if (x.compareTo(best) > 0) best = x;
  return best;
}
// 擦除后签名：static Number max(List)

