public class LinkedList<E> extends AbstractSequentialList<E>
    implements List<E>, Deque<E>, Cloneable, java.io.Serializable {
  transient int size = 0;
  transient Node<E> first;
  transient Node<E> last;

  private static class Node<E> {
    E item; Node<E> next; Node<E> prev;   // 三个引用，内存开销的根源
  }

  Node<E> node(int index) {
    if (index < (size >> 1)) {            // 前半段从头找
      Node<E> x = first;
      for (int i = 0; i < index; i++) x = x.next;
      return x;
    } else {                              // 后半段从尾找
      Node<E> x = last;
      for (int i = size - 1; i > index; i--) x = x.prev;
      return x;
    }
  }
}

static class Node<K,V> implements Map.Entry<K,V> {
  final int hash;
  final K key;
  V value;
  Node<K,V> next;
}

static final class TreeNode<K,V> extends LinkedHashMap.Entry<K,V> {
  TreeNode<K,V> parent;
  TreeNode<K,V> left, right, prev;
  boolean red;
  // 同时保留 next 指针，所以树节点也是链表节点
}

transient Node<K,V>[] table;
transient int size;
int threshold;              // 容量 * loadFactor
final float loadFactor;
transient int modCount;

static final int hash(Object key) {
  int h;
  return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);
}

// 下标计算：n 是 2 的幂时，与运算等价于取模
int index = (n - 1) & hash;

static final int tableSizeFor(int cap) {
  int n = cap - 1;
  n |= n >>> 1; n |= n >>> 2; n |= n >>> 4; n |= n >>> 8; n |= n >>> 16;
  return (n < 0) ? 1 : (n >= MAXIMUM_CAPACITY) ? MAXIMUM_CAPACITY : n + 1;
}
// tableSizeFor(17) == 32, tableSizeFor(16) == 16, tableSizeFor(100) == 128

final V putVal(int hash, K key, V value, boolean onlyIfAbsent, boolean evict) {
  Node<K,V>[] tab; Node<K,V> p; int n, i;
  if ((tab = table) == null || (n = tab.length) == 0)
    n = (tab = resize()).length;                       // 懒初始化
  if ((p = tab[i = (n - 1) & hash]) == null)
    tab[i] = newNode(hash, key, value, null);          // 空桶直插
  else {
    Node<K,V> e; K k;
    if (p.hash == hash && ((k = p.key) == key || (key != null && key.equals(k))))
      e = p;                                           // 首节点就是目标
    else if (p instanceof TreeNode)
      e = ((TreeNode<K,V>)p).putTreeVal(this, tab, hash, key, value);   // 树插入
    else {
      for (int binCount = 0; ; ++binCount) {
        if ((e = p.next) == null) {
          p.next = newNode(hash, key, value, null);    // 尾插
          if (binCount >= TREEIFY_THRESHOLD - 1) treeifyBin(tab, hash);
          break;
        }
        if (e.hash == hash && ((k = e.key) == key || (key != null && key.equals(k)))) break;
        p = e;
      }
    }
    if (e != null) { V old = e.value; if (!onlyIfAbsent || old == null) e.value = value; return old; }
  }
  ++modCount;
  if (++size > threshold) resize();
  return null;
}

static final int TREEIFY_THRESHOLD = 8;      // 链表 -> 树的阈值
static final int UNTREEIFY_THRESHOLD = 6;    // 树 -> 链表的阈值
static final int MIN_TREEIFY_CAPACITY = 64;  // 小于此容量优先扩容

final void treeifyBin(Node<K,V>[] tab, int hash) {
  int n, index; Node<K,V> e;
  if (tab == null || (n = tab.length) < MIN_TREEIFY_CAPACITY)
    resize();                                  // 容量不足，先扩容
  else if ((e = tab[index = (n - 1) & hash]) != null) {
    // 真正的树化逻辑：先串成 TreeNode 链，再 treeify
  }
}

// 泊松分布下链表长度概率（源码注释）：
// 0: 0.60653066  1: 0.30326533  2: 0.07581633  3: 0.01263606
// 4: 0.00157952 5: 0.00015795 6: 0.00001316 7: 0.00000094 8: 0.00000006

final Node<K,V>[] resize() {
  Node<K,V>[] oldTab = table;
  int oldCap = (oldTab == null) ? 0 : oldTab.length;
  int oldThr = threshold;
  int newCap, newThr = 0;
  if (oldCap > 0) {
    if (oldCap >= MAXIMUM_CAPACITY) { threshold = Integer.MAX_VALUE; return oldTab; }
    else if ((newCap = oldCap << 1) < MAXIMUM_CAPACITY && oldCap >= DEFAULT_INITIAL_CAPACITY)
      newThr = oldThr << 1;
  } else if (oldThr > 0) newCap = oldThr;
  else { newCap = DEFAULT_INITIAL_CAPACITY; newThr = (int)(DEFAULT_LOAD_FACTOR * DEFAULT_INITIAL_CAPACITY); }
  // ... 创建新数组，遍历旧桶
  for (int j = 0; j < oldCap; ++j) {
    Node<K,V> e;
    if ((e = oldTab[j]) != null) {
      oldTab[j] = null;
      if (e.next == null) newTab[e.hash & (newCap - 1)] = e;   // 单节点直接定位
      else if (e instanceof TreeNode) ((TreeNode<K,V>)e).split(this, newTab, j, oldCap);
      else {
        Node<K,V> loHead = null, loTail = null, hiHead = null, hiTail = null, next;
        do {
          next = e.next;
          if ((e.hash & oldCap) == 0) {                        // 低位链
            if (loTail == null) loHead = e; else loTail.next = e;
            loTail = e;
          } else {                                             // 高位链
            if (hiTail == null) hiHead = e; else hiTail.next = e;
            hiTail = e;
          }
        } while ((e = next) != null);
        if (loTail != null) { loTail.next = null; newTab[j] = loHead; }
        if (hiTail != null) { hiTail.next = null; newTab[j + oldCap] = hiHead; }
      }
    }
  }
}

