class ArtistCompare implements Comparator<SongV3> {
  @Override
  public int compare(SongV3 one, SongV3 two) {
    return one.getArtist().compareTo(two.getArtist());   // 让 String 干活
  }
}

// 用法
ArtistCompare artistCompare = new ArtistCompare();
songList.sort(artistCompare);            // Java 8+，更短
// Collections.sort(songList, artistCompare);  // 等价的老写法

// Jukebox5：两种排序都用 Comparator，风格统一
class TitleCompare implements Comparator<SongV3> {
  public int compare(SongV3 one, SongV3 two) {
    return one.getTitle().compareTo(two.getTitle());
  }
}
class ArtistCompare implements Comparator<SongV3> {
  public int compare(SongV3 one, SongV3 two) {
