// 不安全发布：其他线程可能看到 null 字段
class Unsafe {
  static Holder holder;                 // 非 volatile
  static void init(){ holder = new Holder(); }
}

// 安全发布：volatile 或 synchronized 或 final 字段
class Safe {
  static volatile Holder holder;
  static void init(){ holder = new Holder(); }
}

// 重排导致的经典问题：可能输出 (0,0) 或其他组合
class Reorder {
  static int a = 0, b = 0;
  static int x = 0, y = 0;
  static void t1(){ a = 1; x = b; }
  static void t2(){ b = 1; y = a; }
