// Mark Word 布局（64 位 JVM，简化）
// 无锁      : [ unused:25 | hashcode:31 | age:4 | biased:1 | lock:01 ]
// 偏向锁    : [ threadId:54 | epoch:2 | age:4 | biased:1 | lock:01 ]
// 轻量级锁  : [ ptr_to_lock_record:62               | lock:00 ]
// 重量级锁  : [ ptr_to_monitor:62                   | lock:10 ]
// GC 标记   : [                           ...        | lock:11 ]

Object o = new Object();
int h = System.identityHashCode(o);   // 之后 o 无法再进入偏向锁

// 对象内存布局（64 位 + 压缩指针）
// header: mark(8) + klass(4) = 12 字节
