// if (q.isEmpty()) wait();   // 虚假唤醒后会读到空队列

// AtomicInteger 的自增实现（简化）
public final int incrementAndGet() {
  int prev, next;
  do {
    prev = get();            // volatile 读
    next = prev + 1;
  } while (!compareAndSet(prev, next));   // CAS 失败就重试
  return next;
}

// ABA 复现与解决
java.util.concurrent.atomic.AtomicInteger ai = new java.util.concurrent.atomic.AtomicInteger(1);
// 线程 1 读到 1，线程 2 把它改成 2 再改回 1，线程 1 的 CAS(1, 新值) 会成功

