}

// 泄漏演示（不要在生产写）
// void leak(){ ThreadLocal<byte[]> tl = new ThreadLocal<>(); tl.set(new byte[10 * 1024 * 1024]); }
// 线程池里的线程长期存活，value 无法回收

java.util.concurrent.ThreadPoolExecutor pool = new java.util.concurrent.ThreadPoolExecutor(
    8,                                   // corePoolSize
    16,                                  // maximumPoolSize
    60L, java.util.concurrent.TimeUnit.SECONDS,   // keepAlive
    new java.util.concurrent.ArrayBlockingQueue<>(200),   // 有界队列
    r -> { Thread t = new Thread(r, "biz-pool-" + r.hashCode()); t.setDaemon(false); return t; },
    new java.util.concurrent.ThreadPoolExecutor.CallerRunsPolicy()   // 反压
);

// 提交
pool.execute(() -> { /* ... */ });

// 优雅关闭
