catch (InterruptedException e) { pool.shutdownNow(); Thread.currentThread().interrupt(); }

java.util.concurrent.ExecutorService io = java.util.concurrent.Executors.newFixedThreadPool(16);

java.util.concurrent.CompletableFuture<String> f =
    java.util.concurrent.CompletableFuture.supplyAsync(() -> queryUser(1), io)      // 异步取用户
        .thenCompose(u -> java.util.concurrent.CompletableFuture.supplyAsync(() -> loadOrders(u), io))  // 依赖串联
        .thenApply(orders -> orders.size())                                        // 同步转换
        .exceptionally(e -> { log(e); return -1; })                                // 兜底
        .whenComplete((r, e) -> System.out.println("done " + r));                  // 收尾

System.out.println(f.join());   // 阻塞获取，异常会包成 CompletionException

// 合并两个独立任务
java.util.concurrent.CompletableFuture<Integer> a = java.util.concurrent.CompletableFuture.supplyAsync(() -> 1, io);
