// 编译器为 record Point(int x, int y) 生成的东西，等价于：
public final class Point extends java.lang.Record {
    private final int x;                       // 一、私有 final 字段
    private final int y;

    public Point(int x, int y) {               // 二、规范构造器
        this.x = x;
        this.y = y;
    }

    public int x() { return x; }               // 三、访问器（同名，无 get 前缀）
    public int y() { return y; }

    @Override public boolean equals(Object o) {  // 四、逐字段比较
        if (this == o) return true;
        if (!(o instanceof Point other)) return false;
        return x == other.x && y == other.y;
    }

    @Override public int hashCode() {           // 五、基于所有字段
        return 31 * Integer.hashCode(x) + Integer.hashCode(y);
    }

    @Override public String toString() {        // 六、类名[字段=值]
        return "Point[x=" + x + ", y=" + y + "]";
    }
}

