// 细粒度同步：只锁必要的几行
public void go() {
  doStuff();                                  // 不碰共享数据 → 不锁，可并发
  synchronized (this) {                       // 锁当前对象（和同步整个方法同一把锁）
    criticalStuff();                          // 这两步必须原子
    moreCriticalStuff();
  }
