// 结果：HashMap 退化为链表，get 从 O(1) 变成 O(n)

static final int hash(Object key) {
    int h;
    return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);
}
// 0x12345678  ->  0x00001234  (>>>16)
// 0x12345678 ^ 0x00001234 = 0x1234444C

// 索引定位：容量 n 是 2 的幂时，& 等价于 %，且永远非负
int index = (n - 1) & hash;

// tableSizeFor：把任意容量向上取到 2 的幂
static final int tableSizeFor(int cap) {
    int n = cap - 1;
    n |= n >>> 1;  n |= n >>> 2;  n |= n >>> 4;
    n |= n >>> 8;  n |= n >>> 16;
    return (n < 0) ? 1 : (n >= MAXIMUM_CAPACITY) ? MAXIMUM_CAPACITY : n + 1;
}
// tableSizeFor(1000) = 1024，阈值 = 1024 * 0.75 = 768

static class Node<K,V> implements Map.Entry<K,V> {
    final int hash;   // 扰动后的哈希，缓存下来避免重算
    final K key;      // key 不可变，防止放入后哈希改变
    V value;
    Node<K,V> next;   // 拉链法的指针
}

// 桶内比较：开销从低到高，短路求值
if (e.hash == hash && ((k = e.key) == key || (key != null && key.equals(k))))

final V putVal(int hash, K key, V value, boolean onlyIfAbsent, boolean evict) {
    Node<K,V>[] tab; Node<K,V> p; int n, i;
    if ((tab = table) == null || (n = tab.length) == 0)
        n = (tab = resize()).length;                 // 1 懒初始化
    if ((p = tab[i = (n - 1) & hash]) == null)
        tab[i] = newNode(hash, key, value, null);     // 2 空桶直接放
    else {
        Node<K,V> e; K k;
        if (p.hash == hash && ((k = p.key) == key || (key != null && key.equals(k))))
            e = p;                                    // 3 头节点命中
        else if (p instanceof TreeNode)
            e = ((TreeNode<K,V>)p).putTreeVal(this, tab, hash, key, value); // 4 树
        else {
            for (int binCount = 0; ; ++binCount) {    // 5 链表
                if ((e = p.next) == null) {
                    p.next = newNode(hash, key, value, null);
                    if (binCount >= TREEIFY_THRESHOLD - 1) treeifyBin(tab, hash);
                    break;
                }
                if (e.hash == hash && ((k = e.key) == key || (key != null && key.equals(k)))) break;
                p = e;
            }
        }
        if (e != null) { V oldValue = e.value; if (!onlyIfAbsent || oldValue == null) e.value = value;
            afterNodeAccess(e); return oldValue; }    // 6 覆盖
    }
    ++modCount;
    if (++size > threshold) resize();                 // 7 扩容
    afterNodeInsertion(evict);
    return null;
}

