// 安全：白名单
private static final Set<String> ALLOWED = Set.of("com.x.A", "com.x.B");
if (!ALLOWED.contains(cls)) throw new IllegalArgumentException("非法类型");

// 反序列化加过滤器
ObjectInputFilter filter = ObjectInputFilter.Config.createFilter("com.x.dto.*;!*");

@Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD)
public @interface Retry {
    int max() default 3;
    long delayMs() default 100;
    double multiplier() default 2.0;
    Class<? extends Throwable>[] on() default {Exception.class};
}

// handler 核心
for (int i = 1; ; i++) {
    try { return method.invoke(target, args); }
    catch (InvocationTargetException e) {
        Throwable cause = e.getCause();
        if (i >= cfg.max() || !retryable(cause, cfg.on())) throw cause;
        Thread.sleep(jitter(cfg.delayMs() * Math.pow(cfg.multiplier(), i - 1)));
    }
}

