    public SonOfBoo(int i) { super("Fred"); }        // OK → Boo(String)
    public SonOfBoo(String s) { super(42); }         // OK → Boo(int)
    public SonOfBoo(int i, String s) { }             // 失败：补 super() 但无 Boo()
    public SonOfBoo(String a,String b,String c) { super(a,b); } // 失败：无 Boo(String,String)
    public SonOfBoo(int i, int j) { super("man", j); }// OK → Boo(String,int)
    public SonOfBoo(int i,int x,int y) { super(i,"star"); } // 失败：无 Boo(int,String)
}

public class Duck {
    int size;          // 实例变量：写在类里、方法外 → 住在堆上的 Duck 对象内部
}

public class Foo {
    public void foo(int x) {       // x 是参数，属于局部变量
        int i = x + 3;              // i 是局部变量
        boolean b = true;           // b 是局部变量
        // x、i、b 都活在 foo() 这一次的栈帧里，方法结束就消失
    }
}

public class CellPhone {
    private Antenna ant;                    // 只在堆上留一个「天线遥控器」的位置
    private Antenna ant2 = new Antenna();   // 额外在堆上造出一个 Antenna 对象，ant2 指向它
}

public class StackDemo {
    public void doStuff() {
        boolean b = true;      // 在 doStuff 的栈帧里
        go(4);                 // go 被压到栈顶，doStuff 暂时被压在下面
        System.out.println("回到 doStuff，b = " + b);   // go 弹走后，b 又可见
    }
    public void go(int x) {
        int z = x + 24;        // 参数 x、局部变量 z 都在 go 的栈帧里
        crazy();               // crazy 被压到最顶上
        System.out.println("回到 go，z = " + z);
    }
    public void crazy() {
        char c = 97;           // 在 crazy 的栈帧里，方法一结束 c 就没了
    }
    public void read() {
        int s = 42;
        sleep();
        System.out.println(s); // 回到 read，s 又可见了
    }
    public void sleep() {
        // s = 7;  // 编译错误：sleep 的栈帧里根本没有 s
    }
}

public class LifeAndScope {
    public void doStuff() {
        boolean b = true;      // b 出生：活着，且在 doStuff 作用域内
        go(4);                 // go 压栈后：b 活着，但不在作用域内
        System.out.println(b); // go 弹栈后：b 又回到作用域，可以打印
    }
    public void go(int x) {
        int z = x + 24;        // x、z 活着且在 go 作用域内
        crazy();               // crazy 压栈后：x、z 活着但不在作用域内
        System.out.println(z); // crazy 弹栈后：z 又可用
    }
    public void crazy() {
        char c = 'a';          // c 活着且在作用域内；方法一结束，c 又死又出作用域
    }
    public void read() {
        int s = 42;            // s 只在 read 的作用域内
        sleep();               // sleep 运行期间：s 活着但不在作用域内
        System.out.println(s); // 回到 read：s 又可见
    }
    public void sleep() {
        // s = 7;              // 编译错误：sleep 的作用域里没有 s
    }
}

public class UseADuck {
    public static void main(String[] args) {
        Duck d = new Duck();     // 这一句会触发 Duck 构造器
    }
}

public class Duck {
    public Duck() {              // 名字和类同名，且没有返回类型 —— 这是构造器
        System.out.println("Quack");   // new 的一瞬间打印，证明构造器真的跑了
    }
}

// 下面两个对照，看清「构造器」和「碰巧同名的方法」的区别：
// public Duck()      { }   → 构造器（无返回类型）
// public void Duck() { }   → 普通方法（有 void），合法但别这么写

// 本章核心模型（Ryan-Monica 的犯罪现场）：
// 读共享数据 → 基于读到的旧值做决定 → 写回共享数据
//   Ryan  : 读 100 → 判断 100>=50 → 写回 50
//   Monica: 读 100(旧值!) → 判断 100>=100 → 写回 0   → 透支！
//
// 关键：查余额和扣钱之间有时间空档，另一条线程能钻进来
// 根源：两条以上线程访问同一个对象的数据（堆上共享对象）
// 线程「被打晕」：被切走时无感知，切回来从冻结点继续，不知数据已被改
// 并发 concurrency ≠ 并行 parallelism：多线程制造并发，是否并行看硬件核数
// 竞态条件 race condition：结果依赖不确定的线程时序

