// ArrayList 不是线程安全的：一写两读也会出问题
List<Chat> chatHistory = new ArrayList<>();          // ← 换成 CopyOnWriteArrayList<> 就好
ExecutorService executor = Executors.newFixedThreadPool(3);
for (int i = 0; i < 5; i++) {
  executor.execute(() -> chatHistory.add(new Chat("Hi there!")));  // 1 个写
  executor.execute(() -> System.out.println(chatHistory));          // 2 个读
  executor.execute(() -> System.out.println(chatHistory));
}
// 元素 Chat 是不可变的（final 类 + final 字段，且 String/LocalDateTime 本身不可变）
// 但容器 ArrayList 可变 → println(集合) 内部 toString() 遍历时若被 add → 抛 ConcurrentModificationException
// 栈轨迹：ArrayList$Itr.checkForComodification ← AbstractCollection.toString ← println
//
// 修法：换成线程安全集合，其余代码一字不改（声明成 List 接口是关键，实现可替换）
List<Chat> safe = new CopyOnWriteArrayList<>();
// 教训：元素不可变 ≠ 容器线程安全；一写多读也会冲突； println 这种「无害」操作也藏着遍历

