// BE the JVM：TwoThreadsWriting
// 两条线程共享一个 Data(内部 ArrayList)，各加 26 个字母，每次 sleep 50ms
// 理论 size=52，实际常小于 52 —— ArrayList 并发 add 丢更新，静默地少数据
// 修法二选一：
// ① public synchronized void addLetter(char c) { letters.add(...); }  // 有读线程时不够
// ② List<String> letters = new CopyOnWriteArrayList<>();              // 写方法不用同步

// 气闸谜案：Tom 把每个子方法都 synchronized —— 错！
// orbiterAirlockExitSequence 调 9 个子方法：
//   verifyPortal → pressurize → openInnerHatch → confirmOccupied → closeInner → ...
// 打断点在「子方法之间」：如 openInnerHatch 与 confirmOccupied 之间被切走 → 内门开着
// 正确：同步最外层编排方法 orbiterAirlockExitSequence()，让整个序列成为一个原子单元
// 教训：每个小部分都锁了 ≠ 整体被锁了；锁必须覆盖「需原子完成的整段逻辑」

// 全书收尾：16章序列化(存数据) → 17章网络+线程(连世界、同时做事) → 18章并发控制(护共享状态)
// 并发纪律：找共享数据 → 界定原子单元 → 精确同步 → 选对工具(锁/CAS/不可变/并发集合)
// 分析框架：坏的是原子性、可见性还是有序性？

Class<?> c = Class.forName("com.example.User");
Object obj = c.getDeclaredConstructor().newInstance();
Method m = c.getDeclaredMethod("getName");
m.setAccessible(true);
Object result = m.invoke(obj);
Field f = c.getDeclaredField("name");
f.setAccessible(true); f.set(obj, "新值");

// 本章两个主角：抽象类与接口（先建立印象，后面逐节讲透）

// 抽象类：不能 new，但能当引用类型、能被继承
public abstract class Animal {
    public abstract void makeNoise();   // 抽象方法：没有方法体
    public void sleep() {               // 具体方法：有实现
        System.out.println("睡觉");
