// 不用 finally：清理代码被迫写两遍
public void bakeBad() {
  try {
    turnOvenOn();
    x.bake();
    turnOvenOff();          // 成功路径要关
  } catch (BakingException e) {
    e.printStackTrace();
    turnOvenOff();          // 失败路径也要关（重复了）
  }
}

// 用 finally：清理逻辑只有一份
public void bakeGood() {
  try {
    turnOvenOn();
    x.bake();
  } catch (BakingException e) {
    e.printStackTrace();
  } finally {
    turnOvenOff();          // 无论成败，一定执行
  }
}

