// 正确：用信号量限制「同时进行的请求数」，而不是限制线程数
private static final Semaphore LIMIT = new Semaphore(64);

void handle(Request req) {
    try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
        executor.submit(() -> {
            LIMIT.acquire();          // 限制下游并发，保护数据库
            try { return callDownstream(req); }
            finally { LIMIT.release(); }
        });
    }
}

// 四种创建方式对比
Thread t1 = Thread.ofVirtual().name("worker-", 0).start(() -> work());
Thread t2 = Thread.startVirtualThread(() -> work());
try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
    ex.submit(() -> work());   // 每个任务一个虚拟线程
}
var factory = Thread.ofVirtual().name("io-", 0).factory();
try (var ex2 = Executors.newThreadPerTaskExecutor(factory)) {
    ex2.submit(() -> work());
}

// 小写 thread = 一条独立执行线索 = 一条独立的调用栈
// 大写 Thread = java.lang.Thread 类，Thread 对象代表一条线程

Thread t = new Thread();  // 造一个 Thread 对象（此时只是普通对象，还没真线程）
t.start();                // 调用 start 才真正启动新栈 —— 但这份线程没工作，立刻就死

// 每个 Java 程序启动时 JVM 会造一个主线程，把 main() 放在栈底
// 线程有自己的：调用栈、程序计数器、局部变量
// 线程共享：堆内存、对象（→ 下一章并发问题的根源）
