// 关闭线程池三件套
ExecutorService pool = Executors.newFixedThreadPool(2);
pool.execute(new LongJob("Long Job"));
pool.execute(new ShortJob("Short Job"));

// ① 温和关闭：现有+排队任务都跑完，拒绝新任务（再提交会抛 RejectedExecutionException）
pool.shutdown();
try {
  // ② 等待关闭完成，最多 5 秒；true=全完成，false=超时（注意：必须先 shutdown 再 await！）
  boolean finished = pool.awaitTermination(5, TimeUnit.SECONDS);
  System.out.println("Finished? " + finished);
} catch (InterruptedException e) { e.printStackTrace(); }
// ③ 兜底强关：尽量中断正在跑的、丢弃排队的；若已关则无副作用
pool.shutdownNow();
// 经典范式：shutdown → awaitTermination(超时) → shutdownNow 兜底
// shutdownNow 只是「请求停止」，任务不响应 interrupt 未必真停（Java 无安全强杀线程之法）

// 第一行：打包地址（不发起连接）
InetSocketAddress serverAddress = new InetSocketAddress("196.164.1.103", 5000);
// IP/主机名 + 端口 装进一个对象；相当于「把收货地址写好」

// 第二行：静态工厂方法 open() —— 创建通道 + 同时发起连接（一步到位）
SocketChannel socketChannel = SocketChannel.open(serverAddress);
// 不是 new SocketChannel(...)，而是类名直接调 open(...)
// open() 会抛 IOException，需要 try-catch 或声明抛出
// 连接建立后：客户端知道服务器 196.164.1.103:5000，服务器也知道客户端的 IP:临时端口

// 连接两要素：IP 地址（哪台机器） + TCP 端口（机器上哪个程序）
InetSocketAddress serverAddress = new InetSocketAddress("196.164.1.103", 5000);
// 196.164.1.103 = 服务器的 IP 地址
// 5000           = TCP 端口（16 位无符号数，0-65535；0-1023 保留给著名服务）
//
// 类比：IP 是购物中心，端口是商场里的某家店
// 著名端口：HTTP=80, HTTPS=443, FTP=20, Telnet=23, POP3=110, SMTP=25, Time=37
// 端口不是硬件插槽，是标识程序的逻辑数字；一个端口只能被一个程序绑定

// 伪共享演示：两个线程各写各的计数器，却共享一个缓存行
final class Pair {
    volatile long a;   // 与 b 相邻，可能落在同一个 64 字节缓存行
    volatile long b;
}

final class PaddedPair {
    volatile long a;
    long p1, p2, p3, p4, p5, p6, p7;  // 用 56 字节把 a 和 b 撑开
    volatile long b;
}
// 同样的逻辑，PaddedPair 在高并发下的吞吐可能高出数倍

// JIT 的「提升」如何把可见性 bug 变成死循环
static boolean flag = false;      // 非 volatile

public static void main(String[] args) throws Exception {
    new Thread(() -> {
        while (!flag) { }         // C2 可能把 flag 提到寄存器，只读一次
        System.out.println("done");
    }).start();

    Thread.sleep(100);
    flag = true;                  // 主线程的写可能永远不被看到
}
// 把 flag 改成 volatile 后循环才能可靠退出

// 四种重排方向与对应的屏障
// StoreStore: 前面的普通写必须先于后面的 volatile 写可见
// StoreLoad : 前面的写必须先于后面的读（最重，x86 上也要 mfence/lock）
// LoadLoad  : 前面的读必须先于后面的读
// LoadStore : 前面的读必须先于后面的写

// x86 上的 volatile 写，JIT 通常生成：
//   mov  [addr], 1
//   lock addl $0, (%rsp)   // 全屏障，顺带禁止 StoreLoad
// ARM64 上则是：
//   stlr w0, [x1]          // store-release
//   ldar w0, [x1]          // load-acquire

// 局部变量天然线程私有，不需要任何同步
public void work() {
    int sum = 0;                  // 栈上，每个线程一份
    for (int i = 0; i < 100; i++) {
        sum += i;                 // 随便改，没有可见性问题
    }
    // 但一旦把 sum 存进字段，它就可能被其它线程看到
    this.lastSum = sum;           // 这一行才需要考虑发布安全
}

// 传递性构造更长的可见性链
class Box {
    int value;                 // 普通字段
    volatile boolean ready;    // 发布标志
}

// 线程 A
box.value = 42;   // ①
box.ready = true; // ② volatile 写

// 线程 B
if (box.ready) {          // ③ volatile 读，② → ③
    int v = box.value;    // ④ 靠 ①→②→③→④ 的传递链，一定看到 42
}

// 锁同时提供互斥与可见性
class Counter {
    private int count;
    private final Object lock = new Object();   // 专用锁对象

    void inc() {
        synchronized (lock) {   // monitorenter：清空副本，重新读主内存
            count++;            // 读-改-写，整段互斥
        }                       // monitorexit：把修改刷回主内存
    }

    int get() {
        synchronized (lock) {   // 不加锁的读可能看到旧值
            return count;
        }
    }
}

// 利用 start 规则：启动前准备的普通字段，子线程一定能看到
class Worker extends Thread {
    private int config;          // 普通字段，不需要 volatile

    Worker(int config) { this.config = config; }

    @Override public void run() {
        System.out.println(config);   // start 之前的写必然可见
    }
}
new Worker(42).start();

// 利用 join 规则：子线程算完，主线程安全取结果
try { t.join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
int r = result;              // join 返回后读取，安全

// volatile 只保证单次读写，不保证复合操作
class Flag {
    private volatile boolean running = true;

    void stop()  { running = false; }        // volatile 写：刷缓冲 + 失效广播
    boolean isRunning() { return running; }  // volatile 读：每次都真实读内存
}

// 这是 volatile 的典型正确用法：一个写者，多个读者，只做信号
// 反例：多个线程同时 running = !running，会丢更新

// volatile 屏障的插入位置（概念示意）
// volatile 写：
//   StoreStore barrier
//   data = 42;        <- 上面的普通写被挡住
//   ready = true;     <- volatile 写
//   StoreLoad barrier

// volatile 读：
//   if (ready) {      <- volatile 读
//       LoadLoad barrier
//       LoadStore barrier
//       read data;    <- 下面的读写被挡住
//   }

// 经典丢更新：volatile 无法拯救 i++
class BadCounter {
    private volatile int count;
    void inc() { count++; }          // 读、加、写三步，可能被交错
    int get()  { return count; }
}

// 三种正确写法
class GoodCounter {
    private int count;
    synchronized void incLock() { count++; }             // 锁

    private final AtomicInteger atom = new AtomicInteger();
    void incAtom() { atom.incrementAndGet(); }           // CAS

    private final LongAdder adder = new LongAdder();
    void incAdder() { adder.increment(); }               // 分散热点
}

// 错误版本：看起来没问题，实际上可能返回半初始化对象
class BadSingleton {
    private static BadSingleton instance;      // 少了 volatile

    private BadSingleton() { /* 假设这里有很多字段初始化 */ }

    static BadSingleton getInstance() {
        if (instance == null) {                // 第一次检查，无锁
            synchronized (BadSingleton.class) {
                if (instance == null) {        // 第二次检查，有锁
                    instance = new BadSingleton();  // 三步可能被重排
                }
            }
        }
        return instance;
    }
}

// 修复一：volatile 版 DCL
class Singleton {
    private static volatile Singleton instance;   // 关键的一处改动
    private Singleton() { }
    static Singleton getInstance() {
        if (instance == null) {
            synchronized (Singleton.class) {
                if (instance == null) instance = new Singleton();
            }
        }
        return instance;
    }
}

// 修复二：静态内部类，靠类加载保证线程安全
class HolderSingleton {
    private HolderSingleton() { }
    private static class Holder { static final HolderSingleton INSTANCE = new HolderSingleton(); }
    static HolderSingleton getInstance() { return Holder.INSTANCE; }
}

// 修复三：枚举，防反射防反序列化
enum EnumSingleton { INSTANCE; }

// final 字段的初始化安全
final class Point {
    private final int x, y;
    Point(int x, int y) { this.x = x; this.y = y; }  // 构造期不逸出 this
    int sum() { return x + y; }                       // 任意发布都安全
}

// this 逃逸的四种典型写法
class Leaky {
    private int value;

    Leaky(EventBus bus) {
        bus.register(this);          // ① 构造期注册监听器
        new Thread(this::work).start(); // ② 构造期启动线程
        Global.CACHE.put("k", this);    // ③ 构造期存入全局容器
        init();                      // ④ 调用可被重写的方法
        value = 42;
    }
    void init() { }                  // 子类可能重写，在 value 赋值前执行
    void work() { System.out.println(value); }
}

// 修复：构造只做赋值，发布另开方法
class Safe {
    private int value;
    Safe(int v) { this.value = v; }
    void start(EventBus bus) { bus.register(this); }  // 构造完成后才调用
}

// 排查清单的代码化表达
class Review {
    // ① 共享可变状态？字段/静态/集合
    private volatile boolean stop;      // ② 只做信号 → volatile 够
    private int count;                  // ③ 复合操作 → 必须锁或原子类
    private final Object lock = new Object();

    void inc() { synchronized (lock) { count++; } }
    int get()  { synchronized (lock) { return count; } }

    // ④ 不可变对象 → 免同步发布
    static final class Snapshot {
        final int a, b;
        Snapshot(int a, int b) { this.a = a; this.b = b; }
    }
    private volatile Snapshot snap = new Snapshot(0, 0);
    void update(int a, int b) { snap = new Snapshot(a, b); }  // 整体替换，读到的永远一致
}

// 并发问题三类性质：
// ① 原子性 atomicity：操作被插队（balance++、查+扣）→ 工具：synchronized、AtomicXXX(CAS)
// ② 可见性 visibility：改了别人看不到（停止标志）→ 工具：volatile、synchronized
// ③ 有序性 ordering：指令重排被别人看出来（data/ready）→ 工具：volatile、synchronized

// volatile 的真实边界：
volatile boolean stop = false;   // 对：一个写多个读的状态标志，写完立刻可见
// volatile int count = 0; count++;  // 错！volatile 不保原子，++ 三步仍丢更新 → 用 AtomicInteger

// 停止标志可见性问题：线程A while(!stop){...}，线程B stop=true
// 没 volatile：A 可能永远读缓存旧值、或 JIT 优化成 while(true)
// 有序性问题：A: data=42; ready=true;  B: if(ready) print(data);
//   重排后 ready 先写 → B 读到 ready=true 但 data=0；volatile ready 禁止这种重排
//
// synchronized 三者全包（原子+可见+有序，happens-before）；volatile 只管可见+部分有序
// 原子变量专注单值原子（内部 volatile + CAS）
// 分析任何并发问题先问：这是原子性、可见性还是有序性出了问题？再选工具

// 锁模型要点
// 每个对象天生一把锁（monitor），任何对象都能当 synchronized(obj) 的锁
// synchronized 方法：进入前必须拿到该对象的钥匙；退出时自动释放（即使抛异常）
//
// 锁是「每对象一把」，不是「每方法一把」：
class Shared {
  synchronized void m1() {}   // 同一对象的 m1、m2、m3 共用一把锁
  synchronized void m2() {}   // 一条线程在 m1 里，别人 m2/m3 都进不去
  synchronized void m3() {}
}
//
// 你锁的不是数据本身（不能写 synchronized int balance），而是访问数据的代码
// 所有会读写同一份数据的路径，必须用同一把锁保护 —— 漏一条就有缺口
// 锁可重入：同一线程可重复进入自己已持有的锁（同步方法调同步方法不会自锁）
// Java 没有加锁 API：JVM 进出同步块自动获取/释放锁
// 休息室：拿不到锁的线程进等待区（BLOCKED），不占 CPU

