// balance++ 不是一步！它约等于：
// int tmp = balance; balance = tmp + 1;  —— 读、改、写三步，中间可被插队

public class LostUpdate {
  public static void main(String[] args) throws InterruptedException {
    ExecutorService pool = Executors.newFixedThreadPool(6);
    Balance balance = new Balance();
    for (int i = 0; i < 1000; i++) pool.execute(() -> balance.increment());
    pool.shutdown();
    if (pool.awaitTermination(1, TimeUnit.MINUTES))  // 等所有任务跑完再打印
      System.out.println("balance = " + balance.balance); // 理论 1000，实际常小于 1000
  }
}
class Balance {
  int balance = 0;
  public synchronized void increment() { balance++; } // 同步后三步成为原子单元，丢更新消失
}
// 丢更新时序：B 读 3 后被切走 → A 把值推到 5 → B 醒来用旧值 3 写回 4 → A 的更新被覆盖
// 修法核心：锁跟着线程走，即使被抢占钥匙也不掉，别人无法插进「读-写」之间
// 经验法则：只同步最少必要的部分（不是 synchronize everything）

// 偏向锁的核心检查（伪代码，JDK 15 前默认开启）
if (markWord.biasedThreadId == currentThread.id) {
    // 直接进入，无需 CAS —— 这就是偏向锁省下的开销
} else {
    // 撤销偏向，升级为轻量级锁，走 CAS + 自旋
}

// 本章核心模型（Ryan-Monica 的犯罪现场）：
// 读共享数据 → 基于读到的旧值做决定 → 写回共享数据
//   Ryan  : 读 100 → 判断 100>=50 → 写回 50
//   Monica: 读 100(旧值!) → 判断 100>=100 → 写回 0   → 透支！
//
// 关键：查余额和扣钱之间有时间空档，另一条线程能钻进来
// 根源：两条以上线程访问同一个对象的数据（堆上共享对象）
// 线程「被打晕」：被切走时无感知，切回来从冻结点继续，不知数据已被改
// 并发 concurrency ≠ 并行 parallelism：多线程制造并发，是否并行看硬件核数
// 竞态条件 race condition：结果依赖不确定的线程时序

