// balance++ 不是一步！它约等于：
// int tmp = balance; balance = tmp + 1;  —— 读、改、写三步，中间可被插队

public class LostUpdate {
  public static void main(String[] args) throws InterruptedException {
    ExecutorService pool = Executors.newFixedThreadPool(6);
    Balance balance = new Balance();
    for (int i = 0; i < 1000; i++) pool.execute(() -> balance.increment());
    pool.shutdown();
    if (pool.awaitTermination(1, TimeUnit.MINUTES))  // 等所有任务跑完再打印
      System.out.println("balance = " + balance.balance); // 理论 1000，实际常小于 1000
  }
}
class Balance {
  int balance = 0;
  public synchronized void increment() { balance++; } // 同步后三步成为原子单元，丢更新消失
}
// 丢更新时序：B 读 3 后被切走 → A 把值推到 5 → B 醒来用旧值 3 写回 4 → A 的更新被覆盖
// 修法核心：锁跟着线程走，即使被抢占钥匙也不掉，别人无法插进「读-写」之间
// 经验法则：只同步最少必要的部分（不是 synchronize everything）

// 并发问题三类性质：
// ① 原子性 atomicity：操作被插队（balance++、查+扣）→ 工具：synchronized、AtomicXXX(CAS)
// ② 可见性 visibility：改了别人看不到（停止标志）→ 工具：volatile、synchronized
// ③ 有序性 ordering：指令重排被别人看出来（data/ready）→ 工具：volatile、synchronized

// volatile 的真实边界：
volatile boolean stop = false;   // 对：一个写多个读的状态标志，写完立刻可见
// volatile int count = 0; count++;  // 错！volatile 不保原子，++ 三步仍丢更新 → 用 AtomicInteger

// 停止标志可见性问题：线程A while(!stop){...}，线程B stop=true
// 没 volatile：A 可能永远读缓存旧值、或 JIT 优化成 while(true)
// 有序性问题：A: data=42; ready=true;  B: if(ready) print(data);
//   重排后 ready 先写 → B 读到 ready=true 但 data=0；volatile ready 禁止这种重排
//
// synchronized 三者全包（原子+可见+有序，happens-before）；volatile 只管可见+部分有序
// 原子变量专注单值原子（内部 volatile + CAS）
// 分析任何并发问题先问：这是原子性、可见性还是有序性出了问题？再选工具

// 陷阱：final 只锁引用，不锁被引用对象的内容
final List<String> letters = new ArrayList<>();
letters.add("a");   // 完全合法！引用没变，但内容变了 → 这个类不是真不可变
// 要真不可变：防御性复制 + 返回不可修改视图 + 元素本身也不可变
this.hosts = List.copyOf(hosts);   // 构造时复制，外部改不到
public List<String> getHosts() { return hosts; } // hosts 已是 List.copyOf 的不可修改列表
// String、LocalDateTime 本身不可变 → final 指向它们才真安全

// Customer/Address 搬家：Address 不可变，靠「造新对象+换引用」更新
// 1. Customer.addr → Address(23 Shiny Street)
// 2. 造新 Address(42 Electric Avenue)
// 3. Customer.addr 改指向新 Address —— 旧对象不动
// 好处：持有旧 Address 的历史订单仍看到旧地址（时间一致性），符合现实
//
// 核心哲学：不是全系统不可变，而是「最小化可变范围」
// 90% 数据类不可变 → 只需为 10% 操心线程安全

