// 老写法：为了关一个文件，把代码写成这样
private void saveFile(File file) {
  BufferedWriter writer = null;                 // 必须声明在 try 外面，finally 才看得见
  try {
    writer = new BufferedWriter(new FileWriter(file));
    for (QuizCard card : cardList) {
      writer.write(card.getQuestion() + "/");
      writer.write(card.getAnswer() + "\n");
    }
    writer.close();                             // 这里若抛异常就轮不到 finally 之外的关闭
  } catch (IOException e) {
    System.out.println("write failed: " + e.getMessage());
  } finally {
    try {                                       // close 自己也会抛异常，再套一层 try-catch
      writer.close();                           // 若 writer 仍是 null，这里会抛 NullPointerException
    } catch (Exception e) {
      System.out.println("close failed: " + e.getMessage());
    }
  }
}

// 新写法：try-with-resources，编译器自动生成 finally
private void saveFile2(File file) {
  try (BufferedWriter writer = new BufferedWriter(new FileWriter(file))) {
    for (QuizCard card : cardList) {
      writer.write(card.getQuestion() + "/");
      writer.write(card.getAnswer() + "\n");
    }
  } catch (IOException e) {
    System.out.println("write failed: " + e.getMessage());
  }
  // 没有 close()：括号里的资源会自动关闭
}

// 多个资源：用分号分隔，关闭顺序与声明顺序相反
private void copyFile(File from, File to) throws IOException {
  try (BufferedReader reader = new BufferedReader(new FileReader(from));
       BufferedWriter writer = new BufferedWriter(new FileWriter(to))) {
    String line;
    while ((line = reader.readLine()) != null) writer.write(line + "\n");
